"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  assignAppeal,
  disqualifyCompetitor,
  ruleAppeal,
  type AppealOut,
  type DisqualifyOut,
} from "@/lib/api";
import {
  ApiErrorAlert,
  FieldMessage,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { StatusBadge } from "@/components/layout/StatusBadge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

export default function AdminAppealsPage() {
  const params = useParams<{ id: string }>();
  const competitionId = params.id;

  const [error, setError] = useState<ApiError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [pending, setPending] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const [appealId, setAppealId] = useState("");
  const [officerId, setOfficerId] = useState("");
  const [assignOut, setAssignOut] = useState<AppealOut | null>(null);

  const [outcome, setOutcome] = useState("UPHELD");
  const [ruleReason, setRuleReason] = useState("");
  const [remedy, setRemedy] = useState("");
  const [ruleOut, setRuleOut] = useState<AppealOut | null>(null);

  const [dqCompetitorId, setDqCompetitorId] = useState("");
  const [dqReason, setDqReason] = useState("");
  const [dqOut, setDqOut] = useState<DisqualifyOut | null>(null);

  function captureErr(err: unknown, fallback: string) {
    if (err instanceof ApiError) {
      setError(err);
      setFieldErrors(fieldErrorMap(err.fields));
    } else {
      setError(
        new ApiError(0, {
          error: {
            code: "HTTP_ERROR",
            message: fallback,
            fields: [],
            traceId: "",
          },
        }),
      );
    }
  }

  async function onAssign(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await assignAppeal(appealId.trim(), officerId.trim());
      setAssignOut(out);
      setStatusMessage(`Appeal assigned — state ${out.state}.`);
    } catch (err) {
      setAssignOut(null);
      captureErr(err, "Could not assign appeal");
    } finally {
      setPending(false);
    }
  }

  async function onRule(e: FormEvent) {
    e.preventDefault();
    if (!ruleReason.trim()) {
      setFieldErrors({ reason: "REASON_REQUIRED" });
      return;
    }
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await ruleAppeal(appealId.trim(), {
        outcome,
        reason: ruleReason.trim(),
        remedy: remedy.trim() || null,
      });
      setRuleOut(out);
      setStatusMessage(`Ruling saved — ${out.rulingOutcome ?? out.state}.`);
    } catch (err) {
      setRuleOut(null);
      captureErr(err, "Could not rule on appeal");
    } finally {
      setPending(false);
    }
  }

  async function onDisqualify(e: FormEvent) {
    e.preventDefault();
    if (!dqReason.trim()) {
      setFieldErrors({ reason: "REASON_REQUIRED" });
      return;
    }
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await disqualifyCompetitor(
        dqCompetitorId.trim(),
        dqReason.trim(),
      );
      setDqOut(out);
      setStatusMessage(`Competitor disqualified (${out.status}).`);
    } catch (err) {
      setDqOut(null);
      captureErr(err, "Could not disqualify competitor");
    } finally {
      setPending(false);
    }
  }

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Appeals & disqualification"
        description="Assign independent officers, rule on cases, and record disqualifications with audited reasons."
      />

      <p className="text-sm text-muted-foreground">
        Competition <span className="font-mono">{competitionId}</span>
      </p>

      {statusMessage ? (
        <Alert data-testid="appeals-status-message">
          <AlertTitle>Status</AlertTitle>
          <AlertDescription>{statusMessage}</AlertDescription>
        </Alert>
      ) : null}

      <ApiErrorAlert error={error} />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Assign officer</CardTitle>
          <CardDescription>
            Conflicted officers are rejected by the API (`OFFICER_CONFLICT`).
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onAssign} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="appealId">Appeal ID</Label>
              <Input
                id="appealId"
                className="min-h-11"
                value={appealId}
                onChange={(e) => setAppealId(e.target.value)}
                required
                data-testid="appeals-appeal-id"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="officerId">Officer user ID</Label>
              <Input
                id="officerId"
                className="min-h-11"
                value={officerId}
                onChange={(e) => setOfficerId(e.target.value)}
                required
                data-testid="appeals-officer-id"
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="appeals-assign"
            >
              Assign
            </Button>
          </form>
          {assignOut ? (
            <Alert className="mt-4" data-testid="appeals-assign-result">
              <AlertTitle className="flex items-center gap-2">
                Assigned <StatusBadge status={assignOut.state} />
              </AlertTitle>
              <AlertDescription>
                Officer{" "}
                <span className="font-mono text-xs">{assignOut.officerId}</span>
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Rule on appeal</CardTitle>
          <CardDescription>
            Outcome UPHELD or DISMISSED. Reason is required.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onRule} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="outcome">Outcome</Label>
              <select
                id="outcome"
                className="flex min-h-11 w-full rounded-lg border border-input bg-background px-3 text-sm"
                value={outcome}
                onChange={(e) => setOutcome(e.target.value)}
                data-testid="appeals-outcome"
              >
                <option value="UPHELD">UPHELD</option>
                <option value="DISMISSED">DISMISSED</option>
              </select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="ruleReason">Reason (required)</Label>
              <Textarea
                id="ruleReason"
                value={ruleReason}
                onChange={(e) => setRuleReason(e.target.value)}
                required
                rows={3}
                data-testid="appeals-rule-reason"
              />
              <FieldMessage message={fieldErrors.reason} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="remedy">Remedy (optional)</Label>
              <Input
                id="remedy"
                className="min-h-11"
                value={remedy}
                onChange={(e) => setRemedy(e.target.value)}
                placeholder="RE_SCORE | RE_RANK | REINSTATE"
                data-testid="appeals-remedy"
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="appeals-rule"
            >
              Save ruling
            </Button>
          </form>
          {ruleOut ? (
            <Alert className="mt-4" data-testid="appeals-rule-result">
              <AlertTitle className="flex items-center gap-2">
                Ruled <StatusBadge status={ruleOut.state} />
              </AlertTitle>
              <AlertDescription>
                {ruleOut.rulingOutcome}
                {ruleOut.remedy ? ` · Remedy ${ruleOut.remedy}` : ""}
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Disqualify competitor</CardTitle>
          <CardDescription>
            Reason must match configured DQ reasons when the API enforces a set.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onDisqualify} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="dqCompetitorId">Competitor ID</Label>
              <Input
                id="dqCompetitorId"
                className="min-h-11"
                value={dqCompetitorId}
                onChange={(e) => setDqCompetitorId(e.target.value)}
                required
                data-testid="appeals-dq-competitor"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="dqReason">Reason (required)</Label>
              <Textarea
                id="dqReason"
                value={dqReason}
                onChange={(e) => setDqReason(e.target.value)}
                required
                rows={3}
                data-testid="appeals-dq-reason"
              />
            </div>
            <Button
              type="submit"
              variant="destructive"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="appeals-disqualify"
            >
              Disqualify
            </Button>
          </form>
          {dqOut ? (
            <Alert className="mt-4" data-testid="appeals-dq-result">
              <AlertTitle className="flex items-center gap-2">
                Disqualified <StatusBadge status={dqOut.status} />
              </AlertTitle>
              <AlertDescription>
                {dqOut.reason}
                {dqOut.promotedCompetitorId
                  ? ` · Promoted ${dqOut.promotedCompetitorId}`
                  : ""}
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <p className="text-xs text-muted-foreground">
        <Link
          href={`/admin/competitions/${competitionId}`}
          className="underline underline-offset-2"
        >
          Back to cycle workspace
        </Link>
      </p>
    </PageShell>
  );
}
